class Solution:
    def maxScore(self, vals, par):
        MOD = 10**9 + 7
        n = len(vals)
        ch = [[] for _ in range(n)]
        for i in range(1, n):
            ch[par[i]].append(i)
        order, st = [], [0]
        while st:
            u = st.pop()
            order.append(u)
            for c in ch[u]: st.append(c)
        dp = [None] * n
        ans = 0
        for u in reversed(order):
            m0 = 0
            for c in str(vals[u]):
                m0 |= 1 << (ord(c) - 48)
            cur = {m0: vals[u], 0: 0}
            for c in ch[u]:
                cd = dp[c]
                nxt = dict(cur)
                for m, a in cur.items():
                    for cm, b in cd.items():
                        k = m | cm
                        if nxt.get(k, -1) < a + b:
                            nxt[k] = a + b
                cur = nxt
            dp[u] = cur
            ans = (ans + max(cur.values())) % MOD
        return ans

