class Solution {
public:
    int maxScore(vector<int>& vals, vector<int>& par) {
        const long long MOD = 1000000007LL;
        int n = vals.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[par[i]].push_back(i);
        vector<int> order; order.reserve(n);
        vector<int> st = {0};
        while (!st.empty()) {
            int u = st.back(); st.pop_back();
            order.push_back(u);
            for (int c : ch[u]) st.push_back(c);
        }
        vector<unordered_map<int,long long>> dp(n);
        long long ans = 0;
        auto dmask = [](long long v) { int m = 0; while (v) { m |= 1 << (v % 10); v /= 10; } return m; };
        for (int idx = n - 1; idx >= 0; idx--) {
            int u = order[idx];
            unordered_map<int,long long> cur;
            cur[dmask(vals[u])] = vals[u];
            cur[0] = 0;
            for (int c : ch[u]) {
                unordered_map<int,long long> nxt = cur;
                for (auto& [m, a] : cur)
                    for (auto& [cm, b] : dp[c]) {
                        int k = m | cm; long long v = a + b;
                        auto it = nxt.find(k);
                        if (it == nxt.end() || it->second < v) nxt[k] = v;
                    }
                cur = move(nxt);
            }
            dp[u] = move(cur);
            long long mx = 0;
            for (auto& [m, v] : dp[u]) mx = max(mx, v);
            ans = (ans + mx) % MOD;
        }
        return (int)ans;
    }
};

