class Solution {
    public int maxScore(int[] vals, int[] par) {
        final long MOD = 1000000007L;
        int n = vals.length;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(par[i]).add(i);
        List<Integer> order = new ArrayList<>();
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0);
        while (!st.isEmpty()) { int u = st.pop(); order.add(u); for (int c : ch.get(u)) st.push(c); }
        Map<Integer,Long>[] dp = new HashMap[n];
        long ans = 0;
        for (int idx = n - 1; idx >= 0; idx--) {
            int u = order.get(idx);
            Map<Integer,Long> cur = new HashMap<>();
            int m0 = 0;
            for (char c : String.valueOf(vals[u]).toCharArray()) m0 |= 1 << (c - '0');
            cur.put(m0, (long) vals[u]);
            cur.put(0, 0L);
            for (int c : ch.get(u)) {
                Map<Integer,Long> nxt = new HashMap<>(cur);
                for (Map.Entry<Integer,Long> e : cur.entrySet())
                    for (Map.Entry<Integer,Long> f : dp[c].entrySet())
                        nxt.merge(e.getKey() | f.getKey(), e.getValue() + f.getValue(), Math::max);
                cur = nxt;
            }
            dp[u] = cur;
            long mx = 0;
            for (long v : cur.values()) mx = Math.max(mx, v);
            ans = (ans + mx) % MOD;
        }
        return (int) ans;
    }
}

