var maxScore = function(vals, par) {
    const MOD = 1e9 + 7;
    const n = vals.length;
    const ch = Array.from({length: n}, () => []);
    for (let i = 1; i < n; i++) ch[par[i]].push(i);
    const order = [], st = [0];
    while (st.length) { const u = st.pop(); order.push(u); for (const c of ch[u]) st.push(c); }
    const dp = new Array(n);
    let ans = 0;
    for (let idx = n - 1; idx >= 0; idx--) {
        const u = order[idx];
        let cur = new Map();
        let m0 = 0;
        for (const c of String(vals[u])) m0 |= 1 << (+c);
        cur.set(m0, vals[u]); cur.set(0, 0);
        for (const c of ch[u]) {
            const nxt = new Map(cur), cd = dp[c];
            for (const [m, a] of cur) for (const [cm, b] of cd) {
                const k = m | cm, v = a + b;
                if (!nxt.has(k) || nxt.get(k) < v) nxt.set(k, v);
            }
            cur = nxt;
        }
        dp[u] = cur;
        let mx = 0;
        for (const v of cur.values()) mx = Math.max(mx, v);
        ans = (ans + mx) % MOD;
    }
    return ans;
};
